"""SQL lectures use the same small relational model and independent check fixtures.
DDL/DML laboratories are explicitly manual: the built-in query runner is read-only.
"""
# slug, title, explanation, query/example, laboratory
SQL = [
('basics','Реляционная модель и первый SELECT','Таблица представляет множество фактов одной структуры. Строка описывает запись, столбец — атрибут, ключ отличает одну запись от другой. SQL задаёт желаемый результат, а движок выбирает способ получения. Не рассчитывай на порядок физического хранения. Начинай с явного списка столбцов: он документирует контракт и не меняется случайно при добавлении нового поля. В учебной базе customers хранит покупателей, orders — заказы. Один покупатель может иметь много заказов, а заказ относится к одному покупателю.', 'SELECT id, name FROM customers ORDER BY id;', 'Выбери id и name всех покупателей по возрастанию id.'),
('projection','Проекция, псевдонимы и выражения','SELECT формирует столбцы результата. AS задаёт понятное имя выражению, но не переименовывает исходную схему. Выражения вычисляются для выбранных строк; тип и поведение преобразований зависят от диалекта. Не используй SELECT * как долговременный контракт отчёта. Если одноимённые столбцы встречаются в нескольких таблицах, квалифицируй их псевдонимом таблицы.', 'SELECT id AS order_id, amount, amount * 2 AS doubled FROM orders ORDER BY id;', 'Выведи id заказа, amount и стоимость двух таких заказов с понятным псевдонимом.'),
('filters','WHERE и сравнения','WHERE оставляет строки, для которых условие истинно. >= включает границу, > исключает её. AND и OR требуют внимательных скобок. Фильтрация выполняется логически до группировки и вычисления окончательной проекции. Проверяй значения по обе стороны порога, а не только один подходящий заказ. NULL не ведёт себя как обычное число и требует отдельной проверки.', 'SELECT id, amount FROM orders WHERE amount >= 25 ORDER BY id;', 'Выведи заказы со стоимостью не меньше 25, включая саму границу.'),
('logic','AND, OR, NOT и полнота условия','Составное условие нужно сначала прочитать словами. AND обычно имеет более высокий приоритет, чем OR, но явные скобки уменьшают риск. NOT применяется к целому предикату, а SQL использует трёхзначную логику при NULL. Разделяй ограничения владельца заказа и стоимости, чтобы OR случайно не открыл другую категорию строк.', 'SELECT id, amount FROM orders WHERE customer_id = 1 AND (amount < 15 OR amount >= 25) ORDER BY id;', 'Выбери заказы покупателя 1 дешевле 15 или не дешевле 25. Проверь, что чужие заказы не проходят.'),
('null','NULL и неизвестное значение','NULL означает отсутствие или неизвестность значения в конкретной модели. Сравнение = NULL не даёт истину: используй IS NULL и IS NOT NULL. WHERE пропускает только TRUE, поэтому UNKNOWN отбрасывается. COUNT(column) не считает NULL, COUNT(*) считает строки. COALESCE выбирает первое ненулевое значение, но ноль и пустая строка сами по себе не являются NULL.', 'SELECT c.id, c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL ORDER BY c.id;', 'Найди покупателей без заказов через LEFT JOIN и проверку отсутствующего ключа.'),
('order','ORDER BY и детерминированность','Порядок результата задаётся только ORDER BY. При равных значениях первого ключа добавь второй устойчивый ключ, иначе пагинация и тесты могут давать разные ответы. ASC и DESC управляют направлением. Положение NULL и сортировка строк зависят от движка и collation. Сортировка может потребовать памяти и временного хранилища.', 'SELECT id, amount FROM orders ORDER BY amount DESC, id ASC;', 'Отсортируй заказы по убыванию суммы и по id при равенстве.'),
('limit','LIMIT, OFFSET и страницы','LIMIT ограничивает число строк, OFFSET пропускает начало. Без детерминированного ORDER BY страница не имеет устойчивого смысла. Большой OFFSET может заставлять движок обработать много пропускаемых строк. Keyset pagination использует последний виденный ключ и лучше подходит для последовательного просмотра больших наборов.', 'SELECT id, amount FROM orders ORDER BY id LIMIT 2;', 'Выведи первые два заказа по id. Затем опиши следующую страницу через условие id > последний_id.'),
('distinct','DISTINCT и кратность строк','SQL-результат обычно допускает повторы. DISTINCT удаляет одинаковые комбинации всех выбранных выражений, а не только первого столбца. Повторы могут быть правильным отражением отношений один-ко-многим. Не добавляй DISTINCT как лекарство от неверного JOIN: сначала установи ожидаемую кратность результата.', 'SELECT DISTINCT customer_id FROM orders ORDER BY customer_id;', 'Выведи уникальные id покупателей, у которых есть заказы.'),
('range','BETWEEN, IN и границы','BETWEEN включает обе границы. IN проверяет принадлежность набору и удобен для нескольких точных значений. NOT IN при NULL в подзапросе может вернуть неожиданный UNKNOWN; для отсутствия связи часто безопаснее NOT EXISTS. Типы значений и неявные преобразования влияют на сравнение.', 'SELECT id, amount FROM orders WHERE amount BETWEEN 10 AND 25 ORDER BY id;', 'Выбери заказы с суммой от 10 до 25 включительно и проверь оба порога.'),
('like','LIKE, шаблоны и текст','LIKE использует % для любой последовательности и _ для одного символа в рамках правил движка. Это не регулярное выражение. Экранирование нужно, когда знак шаблона должен быть буквальным. В SQLite правила регистра для LIKE имеют особенности для Unicode: не обещай универсальную регистронезависимость кириллицы. Collation и нормализация текста являются частью модели поиска.', "SELECT id, name FROM customers WHERE name LIKE 'А%' ORDER BY id;", 'Найди имена, начинающиеся на А. Объясни отличие подстроки и префикса и ограничения регистра.'),
('case','CASE и вычисляемые категории','CASE строит значение по первой подходящей ветви. Без ELSE неподошедшие строки получат NULL. Ветви лучше делать непересекающимися или осознанно упорядоченными. CASE в SELECT не фильтрует строки, а формирует столбец; для отбора нужен WHERE или внешний запрос.', "SELECT id, CASE WHEN amount >= 25 THEN 'large' ELSE 'small' END AS category FROM orders ORDER BY id;", 'Раздели заказы на large и small с границей 25.'),
('aggregate','COUNT, SUM, AVG, MIN и MAX','Агрегат сворачивает множество строк в значение. COUNT(*) на пустом наборе равен нулю, SUM обычно возвращает NULL; при нужном контракте используй COALESCE. AVG считает только ненулевые значения. Для денежных сумм модель единиц важнее удобства дробного вывода. Не выбирай произвольный негруппированный столбец рядом с агрегатом.', 'SELECT COUNT(*) AS count, COALESCE(SUM(amount), 0) AS total FROM orders;', 'Посчитай число заказов и общую сумму. Опиши ожидаемый результат для пустой таблицы.'),
('group','GROUP BY и смысл группы','GROUP BY собирает строки по ключам. Каждый выходной неагрегированный столбец должен быть частью определяющего ключа группы по правилам выбранного диалекта. Группировка по имени может объединить разных людей с одинаковым именем; устойчивый id сохраняет идентичность. Сначала определи, что означает одна строка результата.', 'SELECT customer_id, COUNT(*) AS order_count, SUM(amount) AS total FROM orders GROUP BY customer_id ORDER BY customer_id;', 'Выведи число и сумму заказов каждого покупателя, у которого есть заказы.'),
('having','WHERE и HAVING','WHERE фильтрует исходные строки, HAVING — уже полученные группы. Если сначала отбросить дешёвые заказы, а затем считать сумму, получится другой отчёт, чем отбор покупателей по сумме всех их заказов. Читай логические этапы запроса, чтобы не перемешать эти задачи.', 'SELECT customer_id, SUM(amount) AS total FROM orders GROUP BY customer_id HAVING SUM(amount) >= 35 ORDER BY customer_id;', 'Выбери покупателей с общей суммой заказов не меньше 35.'),
('inner','INNER JOIN и условие связи','INNER JOIN возвращает сочетания строк, для которых условие ON истинно. Связь обычно задаётся внешним ключом и первичным ключом. Один покупатель с двумя заказами появится дважды — по строке на заказ. Пропущенное условие может создать декартово произведение. До написания запроса нарисуй ожидаемые пары ключей.', 'SELECT o.id, c.name, o.amount FROM orders o INNER JOIN customers c ON c.id = o.customer_id ORDER BY o.id;', 'Выведи id заказа, имя покупателя и сумму для каждого заказа.'),
('left','LEFT JOIN и сохранение строк','LEFT JOIN сохраняет все строки слева и подставляет NULL справа при отсутствии совпадения. Условие правой таблицы в WHERE может удалить эти строки и фактически превратить нужную логику в INNER JOIN. Различай фильтрацию совпадений в ON и фильтрацию готового результата в WHERE.', 'SELECT c.name, COUNT(o.id) FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.id, c.name ORDER BY c.id;', 'Посчитай заказы каждого покупателя, включая ноль для покупателя без заказов.'),
('multiplicity','Кратность JOIN и удвоенные суммы','При соединении двух отношений один-ко-многим строки могут размножаться. Если у покупателя два заказа и три адреса, общий JOIN может дать шесть строк. SUM заказа после такого соединения будет завышена. Сначала агрегируй каждую сторону до нужной гранулярности или раздели запрос. DISTINCT не всегда исправляет смысл.', 'WITH totals AS (SELECT customer_id, SUM(amount) AS total FROM orders GROUP BY customer_id) SELECT c.id, COALESCE(t.total, 0) FROM customers c LEFT JOIN totals t ON t.customer_id = c.id ORDER BY c.id;', 'Получи сумму заказов на каждого покупателя, сохранив одну строку на покупателя.'),
('subquery','Подзапросы и независимые вычисления','Подзапрос может вернуть одно значение, набор строк или табличный результат. Скаляром должна быть действительно одна величина. Подзапрос удобен для сравнения со средней суммой или для предварительной агрегации. Читаемость важнее вложенности ради вложенности: промежуточный смысл можно назвать через CTE.', 'SELECT id, amount FROM orders WHERE amount > (SELECT AVG(amount) FROM orders) ORDER BY id;', 'Выведи заказы дороже средней суммы всех заказов.'),
('exists','EXISTS и проверка наличия','EXISTS проверяет, есть ли хотя бы одна подходящая строка. Выбранный список подзапроса не определяет результат наличия. Коррелированный подзапрос использует значение текущей внешней строки. NOT EXISTS часто выразительно описывает отсутствие связи и не имеет ловушки NULL, свойственной некоторым формам NOT IN.', 'SELECT c.id, c.name FROM customers c WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id) ORDER BY c.id;', 'Найди покупателей, имеющих хотя бы один заказ, без размножения строк покупателей.'),
('anti','Антисоединение и отсутствие связи','Задачу «объекты без связанных записей» можно выразить NOT EXISTS или LEFT JOIN с проверкой правого ненулевого ключа на NULL. Проверять nullable-поле данных вместо обязательного ключа опасно: оно может быть NULL и у настоящего совпадения. Укажи, какое именно отношение считается отсутствующим.', 'SELECT c.id, c.name FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id) ORDER BY c.id;', 'Найди покупателей без единого заказа через NOT EXISTS.'),
('cte','WITH и именование этапов','CTE задаёт именованный промежуточный результат внутри одного SQL-оператора. Он помогает разделить выбор строк, агрегацию и оформление. Это не обязательно физическая временная таблица: оптимизатор может встроить выражение или материализовать его. Не используй CTE как обещание производительности без плана и измерения.', 'WITH totals AS (SELECT customer_id, SUM(amount) AS total FROM orders GROUP BY customer_id) SELECT customer_id, total FROM totals WHERE total >= 35 ORDER BY customer_id;', 'Раздели расчёт суммы и фильтрацию покупателей на два понятных этапа WITH.'),
('sets','UNION, UNION ALL, INTERSECT и EXCEPT','Операции над результатами требуют одинакового числа столбцов и совместимого смысла позиций. UNION удаляет дубликаты, UNION ALL сохраняет и обычно дешевле. INTERSECT находит общие строки, EXCEPT — разность. Итоговый порядок задаётся после объединения. Не объединяй несвязанные величины только из-за совпадения типов.', 'SELECT id FROM customers EXCEPT SELECT customer_id FROM orders ORDER BY id;', 'Найди id покупателей без заказов через разность множеств.'),
('window','Оконные функции и сохранение строк','В отличие от GROUP BY, оконный агрегат может вычислять показатель и сохранять исходные строки. OVER задаёт секционирование и порядок. Для накопительных сумм рамка ROWS должна быть явной, чтобы повторы ключа не меняли смысл неожиданно. Оконное значение обычно фильтруют во внешнем запросе или CTE.', 'SELECT id, customer_id, amount, SUM(amount) OVER (PARTITION BY customer_id) AS customer_total FROM orders ORDER BY id;', 'Добавь к каждому заказу общую сумму заказов его покупателя без потери отдельных строк.'),
('ranking','ROW_NUMBER, RANK и равные значения','ROW_NUMBER даёт уникальную последовательную позицию, RANK оставляет пропуски после равенств, DENSE_RANK не оставляет. Для воспроизводимого ROW_NUMBER нужен полный порядок с устойчивым вторым ключом. Ранжирование по категории выполняется через PARTITION BY. Сначала реши, должны ли равные суммы делить одно место.', 'SELECT id, amount, ROW_NUMBER() OVER (ORDER BY amount DESC, id) AS position FROM orders ORDER BY position;', 'Пронумеруй заказы по убыванию суммы, разрешив равенства по id.'),
('running','Накопительные суммы и рамки окна','ORDER BY внутри OVER задаёт порядок окна, но не обязательно порядок окончательного вывода. ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW считает по физическим позициям упорядоченного набора. RANGE может объединять равные ключи иначе. Всегда формулируй, означает ли накопление «до этой строки» или «до этого значения ключа».', 'SELECT id, amount, SUM(amount) OVER (ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total FROM orders ORDER BY id;', 'Посчитай накопительную сумму заказов по id и проверь каждый промежуточный шаг.'),
('lag','LAG, LEAD и сравнение соседей','LAG получает значение предыдущей строки в окне, LEAD — следующей. Первая или последняя строка не имеет соседа и получает значение по умолчанию либо NULL. Порядок должен быть детерминированным. Разница соседних записей не равна разнице соседних календарных дней, если дни пропущены.', 'SELECT id, amount, amount - LAG(amount) OVER (ORDER BY id) AS change FROM orders ORDER BY id;', 'Вычисли изменение суммы относительно предыдущего заказа по id. Объясни NULL у первой строки.'),
('recursive','Рекурсивные CTE и завершение','Рекурсивный CTE имеет начальную часть и шаг, который добавляет новые строки. Требуется условие завершения или защита от циклов в графе. UNION ALL не удаляет повторения. Бесконечная рекурсия расходует ресурсы; встроенный runner DevCat ограничивает время и шаги, но алгоритм всё равно должен иметь собственную границу.', 'WITH RECURSIVE numbers(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM numbers WHERE n < 5) SELECT n FROM numbers ORDER BY n;', 'Сгенерируй числа 1–5 и объясни, почему шестая строка не появится.'),
('schema','Проектирование схемы и ключи','Схема фиксирует сущности, типы полей и ограничения. Первичный ключ идентифицирует запись, внешний ключ связывает сущности. Естественный ключ имеет предметный смысл, суррогатный упрощает независимость от меняющихся атрибутов. NOT NULL и UNIQUE выражают разные требования. Встроенный учебный runner доступен только для чтения: создание схемы выполняй в своей локальной SQLite через IDE или sqlite3 CLI вне защищённой проверки.', 'CREATE TABLE books(id INTEGER PRIMARY KEY, isbn TEXT UNIQUE, title TEXT NOT NULL);', 'Спроектируй библиотеку: books, readers и loans. Укажи ключи, обязательность полей и допустимые связи.'),
('constraints','CHECK, UNIQUE и внешние ключи','Ограничение базы защищает инвариант для всех клиентов. CHECK проверяет выражение, UNIQUE исключает повтор ключа, FOREIGN KEY поддерживает ссылочную целостность. В SQLite контроль внешних ключей зависит от настройки соединения, поэтому её нужно включать явно в собственном приложении. Поведение NULL в ограничениях требует отдельного внимания.', 'CREATE TABLE products(id INTEGER PRIMARY KEY, price_cents INTEGER NOT NULL CHECK(price_cents >= 0));', 'Опиши ограничения товара и попробуй нарушить каждое в отдельной локальной базе. Запиши ожидаемую ошибку.'),
('normalization','Нормализация и аномалии обновления','Если имя покупателя повторяется в каждой строке заказа, изменение имени требует согласованных обновлений. Разделение сущностей уменьшает дублирование и аномалии вставки, изменения и удаления. Нормализация опирается на функциональные зависимости, а не на запрет любых повторов. Денормализацию вводят осознанно под измеренную задачу.', 'SELECT o.id, c.name FROM orders o JOIN customers c ON c.id = o.customer_id ORDER BY o.id;', 'Преобразуй плоскую таблицу заказов с повторяющимися покупателями в связанную схему и объясни зависимости.'),
('insert','INSERT и параметризованные значения','INSERT добавляет запись; явный список столбцов делает код устойчивее к изменению схемы. Значения из пользовательского ввода передаются параметрами API, а не конкатенацией SQL. Плейсхолдер не заменяет имя таблицы или столбца. Для пакета связанных вставок нужна транзакция. DML выполняется в своей локальной базе, встроенная учебная проверка остаётся read-only.', 'INSERT INTO customers(id, name) VALUES (?, ?);', 'Напиши контракт добавления покупателя через параметризованный запрос в выбранном языке. Проверь кавычки в имени.'),
('update','UPDATE, DELETE и безопасное условие','UPDATE и DELETE без WHERE воздействуют на все строки. Сначала выполни SELECT с тем же условием и оцени множество затронутых ключей. Транзакция позволяет проверить результат перед COMMIT. Количество затронутых строк важно для проверки конкурентного изменения и отсутствия объекта. Резервная копия не заменяет корректный контракт.', 'UPDATE products SET price_cents = ? WHERE id = ?;\nDELETE FROM products WHERE id = ?;', 'Спроектируй изменение одного товара с проверкой ровно одной строки. Проведи опыт на копии собственной базы.'),
('transactions','Транзакции и атомарность','Транзакция объединяет несколько операций в единый результат: COMMIT подтверждает, ROLLBACK отменяет. Перевод средств не должен оставлять списание без зачисления. ACID включает атомарность, согласованность, изоляцию и долговечность, но конкретные гарантии зависят от движка и конфигурации. Не держи транзакцию открытой во время долгого диалога с пользователем.', 'BEGIN;\n-- Проверка и связанные изменения\nCOMMIT;\n-- При неуспехе: ROLLBACK;', 'Смоделируй перевод между счетами на локальной базе и принудительный отказ после первого изменения. Проверь откат.'),
('isolation','Конкурентность, блокировки и потерянные обновления','Два клиента могут прочитать одно старое значение и перезаписать изменения друг друга. Атомарное обновление amount = amount + ? и проверка версии помогают выразить операцию корректно. SQLite имеет особенности единственного писателя и режимов журнала. busy_timeout ограничивает ожидание блокировки, но не исправляет алгоритм конкурентного доступа.', 'UPDATE counters SET value = value + 1 WHERE id = ?;', 'Опиши сценарий потерянного обновления двумя соединениями. Выбери атомарную операцию или оптимистическую проверку версии.'),
('indexes','Индексы и цена ускорения','Индекс помогает искать и упорядочивать данные, но занимает место и требует обновления при записи. Составной индекс зависит от порядка столбцов и формы запроса. Низкая избирательность может сделать полный обход дешевле. Индекс не обещает порядок результата без ORDER BY. Решение принимают по плану и измерениям на реалистичном объёме.', 'CREATE INDEX orders_customer_amount ON orders(customer_id, amount);', 'Предложи индекс для заказов покупателя с фильтром суммы. Объясни, какие запросы используют его левый префикс.'),
('plan','EXPLAIN QUERY PLAN и измерение','План показывает, какие таблицы обходятся и какие индексы используются. SEARCH и SCAN отражают разные способы доступа, временная B-tree может указывать на сортировку. План маленькой учебной базы не доказывает производительность на миллионах строк. Сравнивай варианты с одинаковыми данными, прогретым окружением и несколькими повторами.', 'EXPLAIN QUERY PLAN SELECT id, amount FROM orders WHERE customer_id = 1 ORDER BY amount;', 'В своей локальной SQLite сравни план до и после индекса. Запиши время и объём данных; не используй EXPLAIN во встроенной read-only проверке.'),
('security','SQL-инъекции, права и границы данных','SQL-инъекция появляется, когда данные становятся частью исполняемого текста. Параметры сохраняют границу между запросом и значением. Для динамического имени столбца нужен whitelist, а не плейсхолдер. Минимальные права соединения и ограничения размера дополняют параметризацию. Не отправляй реальные персональные данные в учебные примеры.', 'SELECT id, name FROM customers WHERE name = ?;', 'Спроектируй безопасный поиск имени с кавычкой и попыткой инъекции. Объясни, почему значение остаётся строкой.'),
('migration','Миграции, экспорт и резервные копии','Версия схемы позволяет применять последовательные изменения. Перед миграцией нужна проверенная резервная копия, а после — проверка целостности и сценариев приложения. Копирование активного файла SQLite без учёта журнала может быть некорректным; используй поддержанный backup API или согласованный снимок. Экспорт CSV не сохраняет все ограничения и типы схемы.', '-- Версии: 1 -> исходная схема, 2 -> новое поле\n-- Миграция должна быть воспроизводимой и проверяемой', 'Подготовь миграцию библиотеки и восстановление из копии в отдельный каталог. Сравни количество записей и связи.'),
('project','Проект: аналитика магазина','Законченный аналитический проект начинается с вопросов: продажи по покупателям, отсутствие заказов, средний чек, рейтинг и накопительная выручка. Для каждого отчёта укажи гранулярность строки, обработку NULL и порядок. Независимый набор данных должен включать повторяющиеся суммы, пустые связи и покупателей с одинаковыми именами.', 'WITH totals AS (SELECT customer_id, SUM(amount) AS total FROM orders GROUP BY customer_id) SELECT c.id, c.name, COALESCE(t.total, 0) AS total FROM customers c LEFT JOIN totals t ON t.customer_id = c.id ORDER BY total DESC, c.id;', 'Собери восемь отчётов на собственной SQLite-базе. Для каждого напиши контракт, пример вручную, запрос и независимую проверку.'),
('graduation','Итог: самостоятельная база библиотеки','Спроектируй схему с книгами, читателями и выдачами, ограничения и миграции. Напиши запросы доступных книг, просроченных выдач и активности читателей. Добавь параметризованные операции из выбранного языка и транзакции для выдачи. Документация должна объяснять запуск, резервное копирование и восстановление. Умение объяснить план и проверить запрос на независимых данных важнее заученного синтаксиса.', '-- Итоговые артефакты:\n-- schema.sql, migrations/, reports.sql, tests/, README', 'Выпусти локальное приложение библиотеки и покажи восстановление данных. Проведи самопроверку каждого инварианта.'),
]
